def moving_average(xs, k):
    if k < 1 or k > len(xs):
        raise ValueError("bad k")
    s = sum(xs[:k]); out = [s / k]
    for i in range(k, len(xs)):
        s += xs[i] - xs[i - k]
        out.append(s / k)
    return out

