def eval_expr(s: str):
    if not isinstance(s, str) or not s.strip():
        raise ValueError("empty input")

    # ---------- tokenizer ----------
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            # decimal part ?
            if i < n and s[i] == '.':
                if i + 1 < n and s[i + 1].isdigit():
                    i += 1  # '.'
                    j = i
                    while j < n and s[j].isdigit():
                        j += 1
                    i = j
                    num_str = s[start:i]
                    tokens.append(('NUM', float(num_str)))
                    continue
                # '.' not a decimal point, leave it for next iteration
            num_str = s[start:i]
            tokens.append(('NUM', int(num_str)))
            continue
        if c == '*':
            if i + 1 < n and s[i + 1] == '*':
                tokens.append(('STARSTAR', '**'))
                i += 2
                continue
            tokens.append(('STAR', '*'))
            i += 1
            continue
        if c == '/':
            if i + 1 < n and s[i + 1] == '/':
                tokens.append(('DOUBLESLASH', '//'))
                i += 2
                continue
            tokens.append(('SLASH', '/'))
            i += 1
            continue
        if c == '+':
            tokens.append(('PLUS', '+'))
            i += 1
            continue
        if c == '-':
            tokens.append(('MINUS', '-'))
            i += 1
            continue
        if c == '%':
            tokens.append(('PERCENT', '%'))
            i += 1
            continue
        if c == '(':
            tokens.append(('LPAREN', '('))
            i += 1
            continue
        if c == ')':
            tokens.append(('RPAREN', ')'))
            i += 1
            continue
        raise ValueError(f'unknown character {c!r}')

    # ---------- parser ----------
    pos = 0
    def peek():
        return tokens[pos][0] if pos < len(tokens) else None

    def consume(expected=None):
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError('unexpected end')
        typ, val = tokens[pos]
        if expected and typ != expected:
            raise ValueError(f'expected {expected} got {typ}')
        pos += 1
        return typ, val

    def parse_primary():
        typ = peek()
        if typ == 'NUM':
            _, v = consume('NUM')
            return v
        if typ == 'LPAREN':
            consume('LPAREN')
            v = parse_add_sub()
            if peek() != 'RPAREN':
                raise ValueError('unbalanced parentheses')
            consume('RPAREN')
            return v
        raise ValueError('unexpected token')

    def parse_power():
        left = parse_primary()
        if peek() == 'STARSTAR':
            consume('STARSTAR')
            right = parse_unary()
            left = left ** right
        return left

    def parse_unary():
        typ = peek()
        if typ == 'PLUS':
            consume('PLUS')
            return +parse_unary()
        if typ == 'MINUS':
            consume('MINUS')
            return -parse_unary()
        return parse_power()

    def parse_mul_div():
        left = parse_unary()
        while True:
            typ = peek()
            if typ == 'STAR':
                consume('STAR')
                right = parse_unary()
                left = left * right
            elif typ == 'SLASH':
                consume('SLASH')
                right = parse_unary()
                left = left / right
            elif typ == 'DOUBLESLASH':
                consume('DOUBLESLASH')
                right = parse_unary()
                left = left // right
            elif typ == 'PERCENT':
                consume('PERCENT')
                right = parse_unary()
                left = left % right
            else:
                break
        return left

    def parse_add_sub():
        left = parse_mul_div()
        while True:
            typ = peek()
            if typ == 'PLUS':
                consume('PLUS')
                right = parse_mul_div()
                left = left + right
            elif typ == 'MINUS':
                consume('MINUS')
                right = parse_mul_div()
                left = left - right
            else:
                break
        return left

    val = parse_add_sub()
    if pos != len(tokens):
        raise ValueError('extra tokens')
    return val

def parse_csv_line(line: str) -> list[str]:
    n = len(line)
    if n == 0:
        return [""]

    fields = []
    current = []
    in_quotes = False
    i = 0

    while i < n:
        c = line[i]
        if not in_quotes:
            if c == ',':
                fields.append(''.join(current))
                current = []
                i += 1
            elif c == '"':
                if current:
                    raise ValueError('quote in middle of unquoted field')
                in_quotes = True
                i += 1
            else:
                current.append(c)
                i += 1
        else:  # in quotes
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    current.append('"')
                    i += 2
                    continue
                # closing quote
                if i + 1 < n and line[i + 1] != ',':
                    raise ValueError('character after closing quote')
                in_quotes = False
                i += 1
            else:
                current.append(c)
                i += 1

    if in_quotes:
        raise ValueError('unterminated quote')

    fields.append(''.join(current))
    return fields

def parse_csv_line(line: str) -> list[str]:
    fields: list[str] = []
    i = 0
    n = len(line)

    while i <= n:
        # Start of a new field
        if i == n:
            # We are at the end after a trailing comma, so add empty field
            fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1  # skip opening quote
            field_chars = []
            while i < n:
                if line[i] == '"':
                    # Check if it's an escaped quote ""
                    if i + 1 < n and line[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1  # skip closing quote
                        # After closing quote, must be comma or end of line
                        if i < n and line[i] != ',':
                            raise ValueError(f"Unexpected character after closing quote: {line[i]}")
                        break
                else:
                    field_chars.append(line[i])
                    i += 1

            if i < n and line[i] == '"':
                # This shouldn't happen in normal flow, but let's check for unterminated
                pass

            if i == n and line[i - 1] != '"':
                # We finished the loop because i == n, but we need to check if we properly closed
                pass

            # Check if we exited due to end of line without closing quote
            if i < n and line[i] != ',':
                # We already checked this above, but let's be safe
                raise ValueError(f"Unexpected character after closing quote: {line[i]}")

            fields.append("".join(field_chars))

            # If we are not at end of line, the next char must be comma (already verified)
            if i < n:
                i += 1  # skip comma
                continue
            else:
                break

        else:
            # Unquoted field
            field_start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("Unexpected quote in unquoted field")
                i += 1

            fields.append(line[field_start:i])

            if i < n:
                # Must be comma
                if line[i] == ',':
                    i += 1  # skip comma
                    continue
                else:
                    raise ValueError(f"Unexpected character: {line[i]}")
            else:
                break

    return fields

import re

_NUMERIC = re.compile(r'^(0|[1-9]\d*)$')
_IDENT = re.compile(r'^[0-9A-Za-z-]+$')

def _valid_numeric(s: str) -> bool:
    return bool(_NUMERIC.fullmatch(s))

def _parse(version: str):
    if not isinstance(version, str):
        raise ValueError("version must be str")
    v = version.strip()
    if not v:
        raise ValueError("empty version")

    # build metadata
    if '+' in v:
        main_part, build_part = v.split('+', 1)
        if not build_part:
            raise ValueError("empty build metadata")
        for bid in build_part.split('.'):
            if not bid or not _IDENT.fullmatch(bid):
                raise ValueError(f"invalid build identifier {bid!r}")
    else:
        main_part = v

    # pre-release
    if '-' in main_part:
        core_part, pre_part = main_part.split('-', 1)
        if not pre_part:
            raise ValueError("empty pre-release")
        pre_ids = pre_part.split('.')
        for pid in pre_ids:
            if not pid or not _IDENT.fullmatch(pid):
                raise ValueError(f"invalid pre-release identifier {pid!r}")
            if pid.isdigit() and not _valid_numeric(pid):
                raise ValueError(f"numeric pre-release identifier with leading zeros {pid!r}")
    else:
        core_part = main_part
        pre_ids = None

    core_parts = core_part.split('.')
    if len(core_parts) != 3:
        raise ValueError("core version must be MAJOR.MINOR.PATCH")
    major, minor, patch = core_parts
    for n in (major, minor, patch):
        if not _valid_numeric(n):
            raise ValueError(f"invalid numeric component {n!r}")

    return int(major), int(minor), int(patch), pre_ids


def semver_compare(a: str, b: str) -> int:
    ma, mi, pa, pra = _parse(a)
    mb, mj, pb, prb = _parse(b)

    for x, y in ((ma, mb), (mi, mj), (pa, pb)):
        if x != y:
            return 1 if x > y else -1

    if pra is None and prb is None:
        return 0
    if pra is None:
        return 1
    if prb is None:
        return -1

    # both have pre-release
    la, lb = len(pra), len(prb)
    for i in range(min(la, lb)):
        ida, idb = pra[i], prb[i]
        num_a = ida.isdigit()
        num_b = idb.isdigit()
        if num_a and num_b:
            ia, ib = int(ida), int(idb)
            if ia != ib:
                return 1 if ia > ib else -1
        elif not num_a and not num_b:
            if ida != idb:
                return 1 if ida > idb else -1
        else:
            # numeric < non-numeric
            return -1 if num_a else 1

    if la == lb:
        return 0
    return -1 if la < lb else 1

import re


def semver_compare(a: str, b: str) -> int:
    def parse(ver: str):
        # Strip build metadata
        ver = ver.split('+', 1)[0]

        # Split pre-release
        if '-' in ver:
            core, prerelease = ver.split('-', 1)
        else:
            core, prerelease = ver, None

        # Validate core: MAJOR.MINOR.PATCH
        parts = core.split('.')
        if len(parts) != 3:
            raise ValueError(f"Invalid version: {ver}")
        for p in parts:
            if not re.fullmatch(r'0|[1-9]\d*', p):
                raise ValueError(f"Invalid version: {ver}")
        major, minor, patch = (int(p) for p in parts)

        # Validate pre-release
        if prerelease is not None:
            if prerelease == '':
                raise ValueError(f"Invalid version: {ver}")
            ids = prerelease.split('.')
            for ident in ids:
                if ident == '':
                    raise ValueError(f"Invalid version: {ver}")
                if not re.fullmatch(r'[0-9A-Za-z-]+', ident):
                    raise ValueError(f"Invalid version: {ver}")
                # All-digit identifiers must not have leading zeros
                if re.fullmatch(r'\d+', ident):
                    if len(ident) > 1 and ident[0] == '0':
                        raise ValueError(f"Invalid version: {ver}")
        else:
            ids = None

        return (major, minor, patch, ids)

    a_parsed = parse(a)
    b_parsed = parse(b)

    a_m, a_n, a_p, a_ids = a_parsed
    b_m, b_n, b_p, b_ids = b_parsed

    # Compare core version
    if (a_m, a_n, a_p) != (b_m, b_n, b_p):
        if (a_m, a_n, a_p) < (b_m, b_n, b_p):
            return -1
        else:
            return 1

    # Core versions equal, compare pre-release
    if a_ids is None and b_ids is None:
        return 0
    if a_ids is None and b_ids is not None:
        return 1  # no pre-release > has pre-release
    if a_ids is not None and b_ids is None:
        return -1

    # Both have pre-release, compare identifier by identifier
    min_len = min(len(a_ids), len(b_ids))
    for i in range(min_len):
        ai, bi = a_ids[i], b_ids[i]
        ai_num = re.fullmatch(r'\d+', ai)
        bi_num = re.fullmatch(r'\d+', bi)

        if ai_num and bi_num:
            aiv, biv = int(ai), int(bi)
            if aiv != biv:
                return -1 if aiv < biv else 1
        elif ai_num and not bi_num:
            # numeric < non-numeric
            return -1
        elif not ai_num and bi_num:
            return 1
        else:
            # both non-numeric, ASCII order
            if ai != bi:
                return -1 if ai < bi else 1

    # All shared identifiers equal, the one with more is higher
    if len(a_ids) != len(b_ids):
        return -1 if len(a_ids) < len(b_ids) else 1
    return 0

from collections import deque

def keys_maze(grid: list[str]) -> int:
    if not grid:
        raise ValueError("Empty grid")
    cols = len(grid[0])
    for row in grid:
        if len(row) != cols:
            raise ValueError("Rows have different lengths")
    rows = len(grid)

    start = None
    s_cnt = 0
    e_cnt = 0
    for i, row in enumerate(grid):
        for j, ch in enumerate(row):
            if ch == 'S':
                s_cnt += 1
                start = (i, j)
            elif ch == 'E':
                e_cnt += 1
    if s_cnt != 1 or e_cnt != 1 or start is None:
        raise ValueError("Grid must contain exactly one S and one E")

    # masks for keys a..d (4 bits)
    MAX_MASK = 1 << 4
    visited = [[[False] * MAX_MASK for _ in range(cols)] for _ in range(rows)]
    sr, sc = start
    dq = deque()
    dq.append((sr, sc, 0, 0))
    visited[sr][sc][0] = True
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while dq:
        r, c, mask, dist = dq.popleft()
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < rows and 0 <= nc < cols):
                continue
            ch = grid[nr][nc]
            if ch == '#':
                continue

            nmask = mask
            if 'a' <= ch <= 'd':
                bit = 1 << (ord(ch) - ord('a'))
                nmask = mask | bit
            elif 'A' <= ch <= 'D':
                bit = 1 << (ord(ch) - ord('A'))
                if not (mask & bit):
                    continue

            if ch == 'E':
                return dist + 1

            if not visited[nr][nc][nmask]:
                visited[nr][nc][nmask] = True
                dq.append((nr, nc, nmask, dist + 1))

    return -1

from collections import OrderedDict

class LFUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.cap = capacity
        self.key_val = {}          # key -> value
        self.key_freq = {}         # key -> freq
        self.freq_keys = {}        # freq -> OrderedDict(key -> None)  order = LRU
        self.minfreq = 1

    def _increment(self, key):
        old_freq = self.key_freq[key]
        new_freq = old_freq + 1

        od_old = self.freq_keys.get(old_freq)
        if od_old is not None:
            del od_old[key]
            if not od_old:
                del self.freq_keys[old_freq]

        if new_freq not in self.freq_keys:
            self.freq_keys[new_freq] = OrderedDict()
        self.freq_keys[new_freq][key] = None   # most recent in this freq
        self.key_freq[key] = new_freq

    def _evict(self):
        # make sure minfreq points to a non-empty bucket
        while self.minfreq not in self.freq_keys or not self.freq_keys[self.minfreq]:
            self.minfreq += 1
        od = self.freq_keys[self.minfreq]
        evict_key, _ = od.popitem(last=False)   # least recently used
        del self.key_val[evict_key]
        del self.key_freq[evict_key]
        if not od:
            del self.freq_keys[self.minfreq]

    def get(self, key):
        if key not in self.key_val:
            return None
        self._increment(key)
        return self.key_val[key]

    def put(self, key, value):
        if key in self.key_val:
            self.key_val[key] = value
            self._increment(key)
            return
        if len(self.key_val) >= self.cap:
            self._evict()
        self.key_val[key] = value
        self.key_freq[key] = 1
        if 1 not in self.freq_keys:
            self.freq_keys[1] = OrderedDict()
        self.freq_keys[1][key] = None
        self.minfreq = 1

    def __len__(self):
        return len(self.key_val)

from collections import OrderedDict

class LFUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self.cap = capacity
        self.key_node = {}                     # key -> {'value':..., 'freq':...}
        self.freq_map = {}                     # freq -> OrderedDict(key -> node)
        self.min_freq = None

    def _increment(self, key):
        node = self.key_node[key]
        old_freq = node['freq']
        od_old = self.freq_map[old_freq]
        del od_old[key]
        if not od_old:
            del self.freq_map[old_freq]

        node['freq'] += 1
        new_freq = node['freq']
        if new_freq not in self.freq_map:
            self.freq_map[new_freq] = OrderedDict()
        self.freq_map[new_freq][key] = node

        if self.min_freq is None:
            self.min_freq = new_freq
        # if the old minimal frequency disappeared
        if old_freq == self.min_freq and old_freq not in self.freq_map:
            self.min_freq = old_freq + 1
            while self.min_freq not in self.freq_map:
                self.min_freq += 1

    def get(self, key):
        if key not in self.key_node:
            return None
        self._increment(key)
        return self.key_node[key]['value']

    def put(self, key, value):
        if key in self.key_node:
            self.key_node[key]['value'] = value
            self._increment(key)
            return

        if len(self.key_node) >= self.cap:
            # evict least frequent, tie -> least recent
            od = self.freq_map[self.min_freq]
            evict_key, _ = od.popitem(last=False)
            del self.key_node[evict_key]
            if not od:
                del self.freq_map[self.min_freq]
                self.min_freq += 1
                while self.min_freq not in self.freq_map:
                    self.min_freq += 1

        node = {'value': value, 'freq': 1}
        self.key_node[key] = node
        if 1 not in self.freq_map:
            self.freq_map[1] = OrderedDict()
        self.freq_map[1][key] = node
        if self.min_freq is None or 1 < self.min_freq:
            self.min_freq = 1

    def __len__(self):
        return len(self.key_node)

def spiral_order(matrix):
    """Return the elements of a rectangular matrix in clockwise spiral order, starting top-left.
    spiral_order([[1, 2, 3], [4, 5, 6], [7, 8, 9]]) == [1, 2, 3, 6, 9, 8, 7, 4, 5]
    Works for any rectangular shape, including 1 x n, n x 1 and empty ([] or [[]]).
    Raise ValueError if the rows have different lengths."""
    if not matrix:
        return []
    row_len = len(matrix[0])
    for row in matrix:
        if len(row) != row_len:
            raise ValueError("Rows have different lengths")
    if row_len == 0:
        return []

    out = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, row_len - 1

    while top <= bottom and left <= right:
        for c in range(left, right + 1):
            out.append(matrix[top][c])
        top += 1
        if top > bottom:
            break

        for r in range(top, bottom + 1):
            out.append(matrix[r][right])
        right -= 1
        if left > right:
            break

        for c in range(right, left - 1, -1):
            out.append(matrix[bottom][c])
        bottom -= 1
        if top > bottom:
            break

        for r in range(bottom, top - 1, -1):
            out.append(matrix[r][left])
        left += 1

    return out

def spiral_order(matrix):
    """Return the elements of a rectangular matrix in clockwise spiral order, starting top-left.
    spiral_order([[1, 2, 3], [4, 5, 6], [7, 8, 9]]) == [1, 2, 3, 6, 9, 8, 7, 4, 5]
    Works for any rectangular shape, including 1 x n, n x 1 and empty ([] or [[]]).
    Raise ValueError if the rows have different lengths."""
    if not matrix or not matrix[0]:
        return []
    # Validate rectangular shape
    row_len = len(matrix[0])
    for row in matrix:
        if len(row) != row_len:
            raise ValueError("Rows have different lengths")
    out = []
    top, bottom, left, right = 0, len(matrix) - 1, 0, row_len - 1
    while top <= bottom and left <= right:
        # Traverse top row
        for c in range(left, right + 1):
            out.append(matrix[top][c])
        # Traverse right column (skip if only one row left)
        if top < bottom:
            for r in range(top + 1, bottom + 1):
                out.append(matrix[r][right])
        # Traverse bottom row (skip if only one column left)
        if left < right:
            for c in range(right - 1, left - 1, -1):
                out.append(matrix[bottom][c])
        # Traverse left column (skip if single row or column)
        if top < bottom and left < right:
            for r in range(bottom - 1, top, -1):
                out.append(matrix[r][left])
        top, bottom, left, right = top + 1, bottom - 1, left + 1, right - 1
    return out
